# --- 1. Load Libraries ---
library(shiny)
library(bslib)
library(bsicons)
library(shinyjs)
library(DT)

# --- 2. Source External Cube Logic ---
# --- Cube Logic for Blindfolded Trainer ---
# This script contains the core functions for representing,
# manipulating, scrambling, and visualizing a 3x3 cube.

# --- 1. Cube State Representation ---

# Creates a new, solved cube state.
# The cube is represented as a character vector of 54 stickers.
# NEW ORDER: U, L, F, R, B, D.
# Standard orientation: White on top (U), Green in front (F).
create_solved_cube <- function() {
  colors <- c("W", "O", "G", "R", "B", "Y") # U, L, F, R, B, D
  cube_state <- rep(colors, each = 9)
  names(cube_state) <- paste0(rep(c("U", "L", "F", "R", "B", "D"), each=9), 1:9)
  return(cube_state)
}

# --- 2. Move Functions ---

# Helper function to cycle sticker positions
cycle_stickers <- function(cube, indices) {
  temp <- cube[indices[[4]]]
  cube[indices[[4]]] <- cube[indices[[3]]]
  cube[indices[[3]]] <- cube[indices[[2]]]
  cube[indices[[2]]] <- cube[indices[[1]]]
  cube[indices[[1]]] <- temp
  return(cube)
}

# Generic move function that handles clockwise and counter-clockwise turns
apply_move <- function(cube, face_indices, adjacent_indices, is_prime) {
  face_cycle <- list(
    c(face_indices[1], face_indices[3], face_indices[9], face_indices[7]),
    c(face_indices[2], face_indices[6], face_indices[8], face_indices[4])
  )
  if (is_prime) {
    face_cycle <- lapply(face_cycle, rev)
    adjacent_indices <- rev(adjacent_indices)
  }
  cube <- cycle_stickers(cube, face_cycle[[1]])
  cube <- cycle_stickers(cube, face_cycle[[2]])
  cube <- cycle_stickers(cube, adjacent_indices)
  return(cube)
}

# --- Definition of all 12 basic moves (COMPLETELY REBUILT & VERIFIED) ---

# U Move (Up Face): Clockwise cycle is B -> R -> F -> L
move_U <- function(cube, is_prime = FALSE) {
  face_indices <- 1:9
  adjacent <- list(
    c(37, 38, 39), # B face top row
    c(28, 29, 30), # R face top row
    c(19, 20, 21), # F face top row
    c(10, 11, 12)  # L face top row
  )
  apply_move(cube, face_indices, adjacent, is_prime)
}

# L Move (Left Face): Clockwise cycle is U -> F -> D -> B
move_L <- function(cube, is_prime = FALSE) {
  face_indices <- 10:18
  adjacent <- list(
    c(1, 4, 7),     # U face left col
    c(19, 22, 25),  # F face left col
    c(46, 49, 52),  # D face left col
    c(45, 42, 39)   # B face right col (reversed)
  )
  apply_move(cube, face_indices, adjacent, is_prime)
}

# F Move (Front Face): Clockwise cycle is U -> R -> D -> L
move_F <- function(cube, is_prime = FALSE) {
  face_indices <- 19:27
  adjacent <- list(
    c(7, 8, 9),     # U face bottom row
    c(28, 31, 34),  # R face left col
    c(48, 47, 46),  # D face top row (reversed)
    c(18, 15, 12)   # L face right col (reversed)
  )
  apply_move(cube, face_indices, adjacent, is_prime)
}

# R Move (Right Face): Clockwise cycle is U -> B -> D -> F
move_R <- function(cube, is_prime = FALSE) {
  face_indices <- 28:36
  adjacent <- list(
    c(3, 6, 9),     # U face right col
    c(43, 40, 37),  # B face left col (reversed)
    c(48, 51, 54),  # D face right col
    c(21, 24, 27)   # F face right col
  )
  apply_move(cube, face_indices, adjacent, is_prime)
}

# B Move (Back Face): Clockwise cycle is U -> L -> D -> R
move_B <- function(cube, is_prime = FALSE) {
  face_indices <- 37:45
  adjacent <- list(
    c(1, 2, 3),     # U face top row
    c(16, 13, 10),  # L face left col (reversed)
    c(54, 53, 52),  # D face bottom row (reversed)
    c(30, 33, 36)   # R face right col
  )
  apply_move(cube, face_indices, adjacent, is_prime)
}

# D Move (Down Face): Clockwise cycle is F -> R -> B -> L
move_D <- function(cube, is_prime = FALSE) {
  face_indices <- 46:54
  adjacent <- list(
    c(25, 26, 27), # F bottom
    c(34, 35, 36), # R bottom
    c(43, 44, 45), # B bottom
    c(16, 17, 18)  # L bottom
  )
  apply_move(cube, face_indices, adjacent, is_prime)
}

# --- Slice and Wide Moves (NEW) ---

# M move (like L): U -> F -> D -> B
move_M <- function(cube, is_prime = FALSE) {
  adjacent <- list(c(2, 5, 8), c(20, 23, 26), c(47, 50, 53), c(44, 41, 38))
  if (is_prime) { adjacent <- rev(adjacent) }
  cycle_stickers(cube, adjacent)
}

# E move (like D): F -> R -> B -> L
move_E <- function(cube, is_prime = FALSE) {
  adjacent <- list(c(22, 23, 24), c(31, 32, 33), c(40, 41, 42), c(13, 14, 15))
  if (is_prime) { adjacent <- rev(adjacent) }
  cycle_stickers(cube, adjacent)
}

# S move (like F): U -> R -> D -> L
move_S <- function(cube, is_prime = FALSE) {
  adjacent <- list(c(4, 5, 6), c(29, 32, 35), c(51, 50, 49), c(17, 14, 11))
  if (is_prime) { adjacent <- rev(adjacent) }
  cycle_stickers(cube, adjacent)
}

# Wide moves defined by face + slice
move_Uw <- function(cube, is_prime = FALSE) { cube <- move_E(move_U(cube, is_prime), !is_prime); return(cube) }
move_Lw <- function(cube, is_prime = FALSE) { cube <- move_M(move_L(cube, is_prime), is_prime); return(cube) }
move_Fw <- function(cube, is_prime = FALSE) { cube <- move_S(move_F(cube, is_prime), is_prime); return(cube) }
move_Rw <- function(cube, is_prime = FALSE) { cube <- move_M(move_R(cube, is_prime), !is_prime); return(cube) }
move_Bw <- function(cube, is_prime = FALSE) { cube <- move_S(move_B(cube, is_prime), !is_prime); return(cube) }
move_Dw <- function(cube, is_prime = FALSE) { cube <- move_E(move_D(cube, is_prime), is_prime); return(cube) }


# --- 3. Scramble Generation ---

generate_scramble <- function(num_moves = 25) {
  moves <- c("U", "D", "F", "B", "R", "L")
  modifiers <- c("", "'", "2")
  scramble <- character(num_moves)
  last_axis <- ""
  axes <- list(U="UD", D="UD", L="LR", R="LR", F="FB", B="FB")
  
  for (i in 1:num_moves) {
    allowed_moves <- if (i > 1) Filter(function(m) axes[[m]] != last_axis, moves) else moves
    move_choice <- sample(allowed_moves, 1)
    modifier_choice <- sample(modifiers, 1)
    scramble[i] <- paste0(move_choice, modifier_choice)
    last_axis <- axes[[move_choice]]
  }
  return(paste(scramble, collapse = " "))
}

# UPDATED to handle all move types
apply_scramble <- function(cube, scramble_str) {
  moves <- strsplit(scramble_str, " ")[[1]]
  for (full_move in moves) {
    if (full_move == "") next
    
    # Determine the base move (e.g., "R", "Rw", "M")
    base_move <- full_move
    if (grepl("'", full_move) || grepl("2", full_move)) {
      base_move <- substr(full_move, 1, nchar(full_move) - 1)
    }
    
    # Determine the modifier
    modifier <- substr(full_move, nchar(base_move) + 1, nchar(full_move))
    
    move_func <- switch(base_move,
                        "U" = move_U, "L" = move_L, "F" = move_F, "R" = move_R, "B" = move_B, "D" = move_D,
                        "Uw" = move_Uw, "Lw" = move_Lw, "Fw" = move_Fw, "Rw" = move_Rw, "Bw" = move_Bw, "Dw" = move_Dw,
                        "M" = move_M, "E" = move_E, "S" = move_S,
                        stop(paste("Unknown move:", base_move)) # Safety default
    )
    
    if (modifier == "'") {
      cube <- move_func(cube, is_prime = TRUE)
    } else if (modifier == "2") {
      cube <- move_func(cube, is_prime = FALSE); cube <- move_func(cube, is_prime = FALSE)
    } else {
      cube <- move_func(cube, is_prime = FALSE)
    }
  }
  return(cube)
}

# --- 4. Cube Visualization ---

plot_cube <- function(cube) {
  color_map <- c("W" = "white", "G" = "green", "R" = "red", "B" = "blue", "O" = "orange", "Y" = "yellow")
  par(mar = c(1, 1, 1, 1))
  plot(0, 0, type = "n", xlim = c(0, 12), ylim = c(0, 9), xaxt = "n", yaxt = "n", xlab = "", ylab = "", bty = "n")
  draw_face <- function(start_x, start_y, indices) {
    for (i in 1:3) { for (j in 1:3) {
      index <- indices[(i - 1) * 3 + j]
      color <- color_map[cube[index]]
      rect(start_x + j - 1, start_y - i + 1, start_x + j, start_y - i, col = color)
    }}
  }
  face_indices <- list(U = 1:9, L = 10:18, F = 19:27, R = 28:36, B = 37:45, D = 46:54)
  draw_face(3, 9, face_indices$U); draw_face(0, 6, face_indices$L); draw_face(3, 6, face_indices$F)
  draw_face(6, 6, face_indices$R); draw_face(9, 6, face_indices$B); draw_face(3, 3, face_indices$D)
}

plot_cube_numbers <- function() {
  par(mar = c(1, 1, 1, 1))
  plot(0, 0, type = "n", xlim = c(0, 12), ylim = c(0, 9), xaxt = "n", yaxt = "n", xlab = "", ylab = "", bty = "n")
  draw_face_nums <- function(start_x, start_y, indices) {
    for (i in 1:3) { for (j in 1:3) {
      index <- indices[(i - 1) * 3 + j]
      rect(start_x + j - 1, start_y - i + 1, start_x + j, start_y - i, col = "grey90")
      text(start_x + j - 0.5, start_y - i + 0.5, labels = index, cex = 0.8)
    }}
  }
  face_indices <- list(U = 1:9, L = 10:18, F = 19:27, R = 28:36, B = 37:45, D = 46:54)
  draw_face_nums(3, 9, face_indices$U); draw_face_nums(0, 6, face_indices$L); draw_face_nums(3, 6, face_indices$F)
  draw_face_nums(6, 6, face_indices$R); draw_face_nums(9, 6, face_indices$B); draw_face_nums(3, 3, face_indices$D)
}

# --- 5. Blindsolving Logic ---

# --- Lettering Scheme & Setup Moves ---
EDGE_ALG <- "R U R' U' R' F R2 U' R' U' R U R' F'"
CORNER_ALG <- "R U' R' U' R U R' F' R U R' U' R' F R"
PARITY_ALG <- "R U R' F' R U2 R' U2 R' F R U R U2 R' U'"

EDGE_SETUPS <- list(
  A = "Lw2 D' L2", B = "", C = "Lw2 D L2", D = "", E = "L Dw' L", F = "Dw' L", G = "L' Dw' L",
  H = "Dw L'", I = "Lw D' L2", J = "Dw2 L", K = "Lw D L2", L = "L'", M = "", N = "Dw L",
  O = "D2 L' Dw' L", P = "Dw' L'", Q = "Lw' D L2", R = "L", S = "Lw' D' L2", T = "Dw2 L'",
  U = "D' L2", V = "D2 L2", W = "D L2", X = "L2"
)

CORNER_SETUPS <- list(
  A = "", B = "R2", C = "F2 D", D = "F2", E = "", F = "F' D", G = "F'", H = "D' R", I = "F R'",
  J = "R'", K = "F' R'", L = "F2 R'", M = "F", N = "R' F", O = "R2 F", P = "R F", Q = "R D'",
  R = "", S = "D F'", T = "R", U = "D", V = "", W = "D'", X = "D2"
)


# UPDATED to handle all move notations
invert_moves <- function(move_seq) {
  if (is.null(move_seq) || move_seq == "") return("")
  
  moves <- rev(strsplit(move_seq, " ")[[1]])
  inverted <- sapply(moves, function(full_move) {
    if (grepl("'", full_move)) {
      return(substr(full_move, 1, nchar(full_move) - 1)) # Remove prime
    } else if (grepl("2", full_move)) {
      return(full_move) # Is its own inverse
    } else {
      return(paste0(full_move, "'")) # Add prime
    }
  })
  return(paste(inverted, collapse = " "))
}

# Main function to convert a memo into a full solution string
memo_to_solution <- function(edge_memo, corner_memo) {
  
  # Parse memo into individual targets
  edge_targets <- strsplit(edge_memo, "")[[1]]
  corner_targets <- strsplit(corner_memo, "")[[1]]
  
  solution <- c()
  
  # --- Edge Solution ---
  for (target in edge_targets) {
    setup <- EDGE_SETUPS[[target]]
    if (is.null(setup)) next # Skip if letter is not in the list
    
    solution <- c(solution, setup, EDGE_ALG, invert_moves(setup))
  }
  
  # --- Parity Check (MOVED) ---
  has_parity <- (length(edge_targets) %% 2 != 0)
  if (has_parity) {
    solution <- c(solution, PARITY_ALG)
  }
  
  # --- Corner Solution ---
  for (target in corner_targets) {
    setup <- CORNER_SETUPS[[target]]
    if (is.null(setup)) next # Skip if letter is not in the list
    
    solution <- c(solution, setup, CORNER_ALG, invert_moves(setup))
  }
  
  # Clean up and return as a single string
  return(paste(Filter(function(x) x != "", solution), collapse = " "))
}

