# --- 4. Define UI Components ---

# UI for the setup screen
setup_ui <- function() {
  div(id = "setup_panel", card(
    card_header(class = "bg-primary text-white", h4(bs_icon("gear-fill"), "Session Setup", class = "d-flex align-items-center gap-2")),
    card_body(
      checkboxInput("realistic_toggle", "Realistic Mode (random pairs)", value = FALSE),
      conditionalPanel(
        condition = "!input.realistic_toggle",
        p("Specify pairs. The app will randomly apply parity."),
        numericInput("num_edges", "Number of edge pairs:", value = 3, min = 0, max = 11),
        numericInput("num_corners", "Number of corner pairs:", value = 2, min = 0, max = 10)
      ),
      radioButtons("memo_mode", "Pacing:", choices = c("Manual", "Timed"), selected = "Manual", inline = TRUE),
      conditionalPanel(
        condition = "input.memo_mode == 'Timed'",
        sliderInput("time_per_pair", "Seconds per pair:", min = 1, max = 15, value = 3, step = 1)
      ),
      hr(),
      checkboxInput("show_words", "Show dictionary words during memo", value = FALSE),
      actionButton("start_btn", "Start Memorizing", class = "btn-primary btn-lg w-100 mt-3", icon = icon("play-circle"))
    )
  ))
}

