server <- function(input, output, session) {
  
  # --- State Management ---
  app_state <- reactiveVal("setup")
  memo_pairs <- reactiveVal(list()); current_index <- reactiveVal(1); user_recall <- reactiveVal(NULL)
  countdown <- reactiveVal(0); edge_pair_count <- reactiveVal(0); pass_count <- reactiveVal(1)
  final_pass_count <- reactiveVal(0)
  
  # NEW: State for Scramble & Solve Tab
  current_scramble <- reactiveVal(NULL)
  scrambled_cube_state <- reactiveVal(create_solved_cube())
  final_cube_state <- reactiveVal(NULL)
  solution_alg <- reactiveVal("")
  
  # --- Dictionary Management ---
  DB_FILE <- "word_database.rds"
  word_db <- reactiveVal()
  if (file.exists(DB_FILE)) { word_db(readRDS(DB_FILE)) } else {
    default_db <- create_default_db(); word_db(default_db); saveRDS(default_db, DB_FILE)
  }
  
  # --- Letter Pools ---
  EDGE_LETTERS_POOL <- setdiff(LETTERS[1:24], c("B", "M"))
  CORNER_LETTERS_POOL <- setdiff(LETTERS[1:24], c("A", "R", "E"))
  
  main_timer <- reactiveTimer(1000)
  
  # --- Panel Visibility Control ---
  observeEvent(app_state(), {
    panels <- c("setup_panel", "memo_panel", "recall_panel", "results_panel")
    current_panel <- paste0(app_state(), "_panel")
    for (panel in panels) { shinyjs::hide(id = panel, anim = FALSE) }
    shinyjs::show(id = current_panel, anim = TRUE, animType = "fade")
  })
  
  # --- Event Handlers (Trainer Tab) ---
  observeEvent(input$start_btn, {
    set.seed(as.numeric(Sys.time())); num_edge_pairs <- 0; num_corner_pairs <- 0
    if (isTRUE(input$realistic_toggle)) { num_edge_pairs <- sample(5:7, 1); num_corner_pairs <- sample(4:6, 1) } else {
      if (is.null(input$num_edges) || is.na(input$num_edges) || is.null(input$num_corners) || is.na(input$num_corners)) {
        showNotification("Please enter a valid number of pairs.", type = "error"); return()
      }
      num_edge_pairs <- input$num_edges; num_corner_pairs <- input$num_corners
    }
    if (num_edge_pairs + num_corner_pairs <= 0) { showNotification("Please specify at least one pair.", type = "warning"); return() }
    has_parity <- sample(c(TRUE, FALSE), 1)
    num_edge_targets <- num_edge_pairs * 2; num_corner_targets <- num_corner_pairs * 2
    if (has_parity) {
      if (num_edge_targets > 0) num_edge_targets <- num_edge_targets - 1
      if (num_corner_targets > 0) num_corner_targets <- num_corner_targets - 1
    }
    if (num_edge_targets > length(EDGE_LETTERS_POOL)) { showNotification(paste("Too many edge targets. Max:", length(EDGE_LETTERS_POOL)), type = "error"); return() }
    if (num_corner_targets > length(CORNER_LETTERS_POOL)) { showNotification(paste("Too many corner targets. Max:", length(CORNER_LETTERS_POOL)), type = "error"); return() }
    edge_letters <- if(num_edge_targets > 0) sample(EDGE_LETTERS_POOL, num_edge_targets, replace = FALSE) else character(0)
    corner_letters <- if(num_corner_targets > 0) sample(CORNER_LETTERS_POOL, num_corner_targets, replace = FALSE) else character(0)
    create_pairs <- function(l) { if (length(l) == 0) return(list()); sapply(seq(1, length(l), by = 2), function(i) if (i + 1 <= length(l)) paste0(l[i], l[i+1]) else l[i]) }
    edge_p <- create_pairs(edge_letters); corner_p <- create_pairs(corner_letters)
    memo_pairs(c(as.list(edge_p), as.list(corner_p))); edge_pair_count(length(edge_p)); current_index(1); pass_count(1)
    if (input$memo_mode == "Timed") { countdown(input$time_per_pair) }
    app_state("memo")
  })
  
  advance_pair <- function() {
    if (current_index() < length(memo_pairs())) { current_index(current_index() + 1) } else { current_index(1); pass_count(pass_count() + 1) }
    if (input$memo_mode == "Timed") { countdown(input$time_per_pair) }
  }
  observeEvent(input$next_btn, { advance_pair() })
  observeEvent(input$finish_memo_btn, { final_pass_count(pass_count()); app_state("recall") })
  observeEvent(main_timer(), { req(app_state() == "memo", input$memo_mode == "Timed"); new_time <- countdown() - 1; countdown(new_time); if (new_time < 0) { advance_pair() } })
  observeEvent(input$check_btn, { user_text <- toupper(trimws(input$recall_text)); recalled_list <- strsplit(user_text, "\\s+")[[1]]; if (length(recalled_list) == 1 && recalled_list[1] == "") { recalled_list <- character(0) }; user_recall(recalled_list); app_state("results") })
  observeEvent(input$new_session_btn, { shinyjs::reset("recall_text"); memo_pairs(list()); current_index(1); user_recall(NULL); countdown(0); edge_pair_count(0); pass_count(1); final_pass_count(0); app_state("setup") })
  
  # --- Event Handlers (Scramble & Solve Tab) ---
  observeEvent(input$generate_scramble_btn, {
    scramble <- generate_scramble()
    current_scramble(scramble)
    scrambled_cube_state(apply_scramble(create_solved_cube(), scramble))
    final_cube_state(NULL) # Clear previous result
    solution_alg("") # Clear previous algorithm
  })
  
  observeEvent(input$check_solution_btn, {
    req(current_scramble()) # Require a scramble to be active
    
    # FIX: Apply toupper() first, then remove invalid characters.
    edge_memo <- gsub("[^A-X]", "", toupper(input$edge_memo_input))
    corner_memo <- gsub("[^A-X]", "", toupper(input$corner_memo_input))
    
    alg <- memo_to_solution(edge_memo, corner_memo)
    solution_alg(alg)
    
    result_cube <- apply_scramble(scrambled_cube_state(), alg)
    final_cube_state(result_cube)
  })
  
  # --- Output Rendering (Trainer Tab) ---
  output$memo_progress_text <- renderText({ e_count <- edge_pair_count(); c_count <- length(memo_pairs()) - e_count; idx <- current_index(); pass_str <- paste0("Pass ", pass_count(), " | "); if (idx <= e_count) paste0(pass_str, "Edge Pair ", idx, " of ", e_count) else paste0(pass_str, "Corner Pair ", idx - e_count, " of ", c_count) })
  output$letter_pair <- renderText({ req(length(memo_pairs()) > 0, current_index() <= length(memo_pairs())); memo_pairs()[[current_index()]] })
  output$memo_word <- renderText({ req(input$show_words, length(memo_pairs()) > 0); current_pair <- memo_pairs()[[current_index()]]; db <- word_db(); word_row <- db[db$Pair == current_pair, ]; if (nrow(word_row) > 0) { word_row$Word[1] } else { "[No word found]" } })
  output$countdown_display <- renderUI({ tags$h3(class = "text-center text-warning fw-bold", countdown()) })
  output$countdown_progress <- renderUI({ req(input$memo_mode == "Timed"); percent <- (countdown()/input$time_per_pair)*100; tags$div(class="progress", style="height:20px;", tags$div(class="progress-bar progress-bar-striped bg-warning", role="progressbar", style=paste0("width:",percent,"%;"))) })
  output$pass_count_results_text <- renderUI({ req(app_state() == "results"); tags$h5(paste("Total Passes Taken:", final_pass_count()), align = "center", style = "margin-bottom: 20px; color: #00bc8c;") })
  output$results_table <- renderTable({ req(!is.null(user_recall())); original_seq <- unlist(memo_pairs()); recalled_seq <- user_recall(); length(recalled_seq) <- length(original_seq); recalled_seq[is.na(recalled_seq)] <- "---"; status <- ifelse(original_seq == recalled_seq, "✔️ Correct", "❌ Incorrect"); e_count <- edge_pair_count(); c_count <- length(original_seq) - e_count; types <- c(rep("Edge", e_count), rep("Corner", c_count)); pair_numbers <- c(if (e_count > 0) 1:e_count else integer(0), if (c_count > 0) 1:c_count else integer(0)); data.frame(Type=types, Pair=pair_numbers, Correct=original_seq, Your_Answer=recalled_seq, Status=status) }, striped=TRUE, hover=TRUE, bordered=TRUE, spacing="m", align="c")
  
  # --- Output Rendering (Scramble & Solve Tab) ---
  output$scramble_text <- renderText({ if(is.null(current_scramble())) "Click the button to generate a scramble." else current_scramble() })
  
  # UPDATED to use renderImage for correct aspect ratio
  output$scrambled_cube_plot <- renderImage({
    width  <- session$clientData$output_scrambled_cube_plot_width
    if (is.null(width)) { width <- 400 }
    height <- width * (9 / 12)
    outfile <- tempfile(fileext = '.png')
    png(outfile, width = width, height = height, bg = "transparent")
    plot_cube(scrambled_cube_state())
    dev.off()
    list(src = outfile, contentType = 'image/png', width = "100%", height = "auto", alt = "Scrambled cube")
  }, deleteFile = TRUE)
  
  output$solution_alg_text <- renderText({ if(solution_alg() == "") "Your solution algorithm will appear here." else solution_alg() })
  
  # UPDATED to use renderImage for correct aspect ratio
  output$solved_cube_plot <- renderImage({
    cube_to_plot <- if(is.null(final_cube_state())) create_solved_cube() else final_cube_state()
    width  <- session$clientData$output_solved_cube_plot_width
    if (is.null(width)) { width <- 400 }
    height <- width * (9 / 12)
