    dev.off()
    list(src = outfile, contentType = 'image/png', width = "100%", height = "auto", alt = "Solved cube")
  }, deleteFile = TRUE)
  
  # FIX: Improved solved check using identical()
  is_solved <- function(cube) {
    return(identical(cube, create_solved_cube()))
