  # --- Output Rendering (Dictionary Tab) ---
  output$dictionary_table <- renderDT({ datatable(word_db(), editable=list(target="cell", disable=list(columns=0)), options=list(pageLength=15)) })
  observeEvent(input$dictionary_table_cell_edit, { info <- input$dictionary_table_cell_edit; db <- word_db(); db[info$row, info$col] <- info$value; word_db(db); saveRDS(db, DB_FILE); showNotification("Word updated!", type="message", duration=2) })
